class Shape {
public:
    virtual ~Shape() = default;          // Essential virtual destructor
    virtual void draw() const = 0;       // Pure virtual function (Interface)
};

class Circle : public Shape {
public:
    void draw() const override { /* Circle impl */ }
};

// Dynamic dispatch using base pointer
Shape* s_ptr = new Circle();
s_ptr->draw(); // Invokes Circle::draw() at runtime
delete s_ptr;

// Note: If Base::draw was non-virtual,
// s_ptr->draw() would always invoke Base::draw()
